-- public.messages RLS
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();

-- Threads: announcement (A), group (G: coach, par1, par3), direct (D: par1 <-> par3)
set local role anon; select set_config('request.jwt.claims', '{"role":"anon"}', true);
select throws_ok($$ select 1 from public.messages $$, '42501', null, 'anonymous has no access');
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000001","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.messages where true), 4, 'par1 (joined 10 days ago) reads the group history, dm and announcement');
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000003","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.messages where thread_id='71000000-0000-0000-0000-00000000000b'), 1, 'par3 joined 1 day ago: only messages from then on');
select is((select count(*)::int from public.messages where id='81000000-0000-0000-0000-000000000001'), 0, 'older group message is invisible to a late joiner');
reset role; select set_config('request.jwt.claims', '{"sub":"aa000000-0000-0000-0000-000000000002","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.messages where thread_id='71000000-0000-0000-0000-00000000000b'), 2, 'staff see the full history');
reset role; select set_config('request.jwt.claims', '{"sub":"aa000000-0000-0000-0000-000000000001","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.messages where thread_id='71000000-0000-0000-0000-00000000000b'), 2, 'a team admin reads group messages for oversight');
select is((select count(*)::int from public.messages where thread_id='71000000-0000-0000-0000-00000000000c'), 0, 'a team admin cannot read others direct messages');
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000002","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.messages where true), 1, 'a non-participant parent reads only the announcement');
reset role; select set_config('request.jwt.claims', '{"sub":"cc000000-0000-0000-0000-000000000001","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.messages where true), 1, 'a teen not in the group reads only the announcement');
reset role; select set_config('request.jwt.claims', '{"sub":"dd000000-0000-0000-0000-000000000002","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.messages where true), 0, 'another teams parent reads nothing');
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000001","role":"authenticated"}', true); set local role authenticated;
select throws_ok($$ insert into public.messages (thread_id, sender_profile_id, body) values ('71000000-0000-0000-0000-00000000000b','bb000000-0000-0000-0000-000000000001','x') $$, '42501', null, 'clients cannot insert messages directly');
select throws_ok($$ update public.messages set body='x' $$, '42501', null, 'clients cannot edit messages directly');
select throws_ok($$ delete from public.messages $$, '42501', null, 'clients cannot delete messages directly');
reset role;
select * from finish();
rollback;
